import{_ as n,C as l,o as h,c,ag as r,E as s,w as a,a as t,j as i}from"./chunks/framework.BSwSpTvy.js";const k=JSON.parse('{"title":"🌐 Headless Chromium Web Search","description":"","frontmatter":{},"headers":[],"relativePath":"features/tools/search.md","filePath":"features/tools/search.md"}'),d={name:"features/tools/search.md"};function u(g,e,m,p,f,x){const o=l("ZedChat");return h(),c("div",null,[e[5]||(e[5]=r('<h1 id="🌐-headless-chromium-web-search" tabindex="-1">🌐 Headless Chromium Web Search <a class="header-anchor" href="#🌐-headless-chromium-web-search" aria-label="Permalink to &quot;🌐 Headless Chromium Web Search&quot;">​</a></h1><p>The integrated web search engine allows the Zed agent to access the live internet, bypassing the static knowledge cutoff of modern Large Language Models.</p><h2 id="the-headless-engine" tabindex="-1">The Headless Engine <a class="header-anchor" href="#the-headless-engine" aria-label="Permalink to &quot;The Headless Engine&quot;">​</a></h2><p>Unlike simple text-scrapers that fail on modern documentation sites (React, Next.js, Docusaurus), this fork utilizes the <strong>Chromiumoxide</strong> library to instantiate a localized, headless Chromium instance.</p><p>This ensures:</p><ul><li><strong>Full JavaScript Execution</strong>: Rendered code snippets and dynamic content are fully visible.</li><li><strong>DOM-to-Markdown Transformation</strong>: After rendering, we traverse the DOM to extract clean, hierarchical Markdown for the agent&#39;s context.</li></ul><h2 id="navigation-extraction-process" tabindex="-1">Navigation &amp; Extraction Process <a class="header-anchor" href="#navigation-extraction-process" aria-label="Permalink to &quot;Navigation &amp; Extraction Process&quot;">​</a></h2><p>The agent utilizes two tools under the hood:</p><ol><li><strong><code>search</code></strong>: Queries the DuckDuckGo API to find relevant URLs.</li><li><strong><code>browser</code></strong>: Navigates to a specific URL, waits for hydrations, and extracts the content.</li></ol><h2 id="visual-walkthrough" tabindex="-1">Visual Walkthrough <a class="header-anchor" href="#visual-walkthrough" aria-label="Permalink to &quot;Visual Walkthrough&quot;">​</a></h2><h3 id="stage-1-discovering-the-solution" tabindex="-1">Stage 1: Discovering the Solution <a class="header-anchor" href="#stage-1-discovering-the-solution" aria-label="Permalink to &quot;Stage 1: Discovering the Solution&quot;">​</a></h3>',11)),s(o,null,{user:a(()=>[...e[0]||(e[0]=[t(" How do I fix Rust error E0277 in the latest version of Axum? ",-1)])]),assistant:a(()=>[...e[1]||(e[1]=[t(" I need to search the live web as my training data doesn't cover the most recent Axum release. ",-1)])]),output:a(()=>[...e[2]||(e[2]=[t(' @search({ query: "axum rust error E0277 trait bound not satisfied" }) >> Result 1: https://docs.rs/axum/latest/axum/error_handling/index.html >> Result 2: https://github.com/tokio-rs/axum/issues/1234 ',-1)])]),_:1}),e[6]||(e[6]=i("h3",{id:"stage-2-deep-extraction",tabindex:"-1"},[t("Stage 2: Deep Extraction "),i("a",{class:"header-anchor",href:"#stage-2-deep-extraction","aria-label":'Permalink to "Stage 2: Deep Extraction"'},"​")],-1)),s(o,null,{assistant:a(()=>[...e[3]||(e[3]=[t(" The docs.rs page looks most relevant. I am now navigating to the page to extract the precise fix. ",-1)])]),output:a(()=>[...e[4]||(e[4]=[t(' @browser({ action: "navigate", target: "https://docs.rs/axum/latest/axum/error_handling/index.html" }) >> Status: Page Rendered (JS Hydrated) >> Extracted: [Comprehensive Markdown summary of the fix...] ',-1)])]),_:1}),e[7]||(e[7]=r('<h2 id="technical-details" tabindex="-1">Technical Details <a class="header-anchor" href="#technical-details" aria-label="Permalink to &quot;Technical Details&quot;">​</a></h2><ul><li><strong>Containerization</strong>: Rendering happens entirely within a local chromium process.</li><li><strong>Privacy</strong>: No tracking tokens are sent; we mimic standard Chrome headers to bypass basic anti-bot triggers.</li><li><strong>Code Path</strong>: Implemented in <code>crates/agent/src/tools/web_search_tool.rs</code>.</li></ul><h2 id="workflow-impact" tabindex="-1">Workflow Impact <a class="header-anchor" href="#workflow-impact" aria-label="Permalink to &quot;Workflow Impact&quot;">​</a></h2><ul><li><strong>Infinite Knowledge</strong>: Bypasses the LLM training cutoff by pulling live data from the web.</li><li><strong>Multi-Source Synthesis</strong>: The agent can read multiple search results to form a consensus on the best approach.</li><li><strong>Free &amp; Local</strong>: No need for paid Search API keys (Serper, Tavily). Uses your local machine&#39;s Chromium instance.</li><li><strong>Developer-Focused</strong>: Prioritizes documentation sites (docs.rs, GitHub, MDN) over generic SEO content.</li></ul>',4))])}const v=n(d,[["render",u]]);export{k as __pageData,v as default};
